/* El HTTP Request puede devolver un item por aviso o un arreglo, según la versión de n8n. Normalizamos ambas formas y no dejamos pasar datos ajenos al contrato. */
const lista = $input.all().flatMap(({ json }) => Array.isArray(json) ? json : Array.isArray(json?.body) ? json.body : [json]);
const fecha = /^\d{4}-\d{2}-\d{2}$/;
return lista.flatMap((aviso) => {
  const idDriver = Number(aviso?.idDriver);
  const tipo = aviso?.tipo;
  const chatId = String(aviso?.chatId ?? '').trim();
  const texto = String(aviso?.texto ?? '').trim();
  if (!fecha.test(String(aviso?.fechaOperacion ?? '')) || !fecha.test(String(aviso?.jornada ?? '')) || !Number.isSafeInteger(idDriver) || idDriver <= 0 || !['DRIVER', 'OPERATIVO'].includes(tipo) || !chatId.endsWith('@g.us') || !texto) return [];
  return [{ json: { fechaOperacion: aviso.fechaOperacion, jornada: aviso.jornada, idDriver, tipo, chatId, texto } }];
});
